
select "INVENTORY_ON_HAND"."INVENTORY_DATE" "Inventory_Date", decode("INVENTORY_ON_HAND"."BRANCH_PLANT", 'CINC', 'Americas', 'CIN2', 'Americas', 'CIN4', 'Americas', 'AUBA', 'Aubange', 'AUB2', 'Aubange', 'SING', 'Singapore', 'SNG4', 'Singapore', 'MUM3', 'India', 'SHAN', 'China', 'ERROR') "REGION", "INVENTORY_ON_HAND"."BRANCH_PLANT" "Branch_Plant", "ITEM"."GLOBAL_BULK_ITEM" "Global_Bulk_Item", "ITEM"."BULK_ITEM" "Bulk_Item", "INVENTORY_ON_HAND_MEASURE"."ITEM_NUMBER_2ND" "C_2nd_Item_Number", "ITEM"."STOCK_TYPE_CODE" "Stock_Type_Code", "INVENTORY_ON_HAND"."GL_CLASS_CODE" "GL_Class_Code", "INVENTORY_ON_HAND"."LOCATION" "Location", "INVENTORY_ON_HAND"."LOT_NUMBER" "Lot_Number", "ITEM_LOT_NUMBER_ALIAS"."SUPPLIER_LOT_NUMBER" "Supplier_Lot_Number", "INVENTORY_ON_HAND_MEASURE"."LOT_STATUS" "Lot_Status", "INVENTORY_ON_HAND"."MASTER_PLANNING_FAMILY" "Master_Planning_Family", sum("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND") "Quantity_on_Hand", "INVENTORY_ON_HAND_MEASURE"."UNIT_OF_MEASURE" "Primary_Unit_of_Measure", sum(case  when "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_KG"<0 then -(("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_KG")*20) else "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_KG" end ) "Quantity_on_Hand_KGs", sum(case  when "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_LB"<0 then -(("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_LB")*44) else "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_LB" end ) "Quantity_on_Hand_LBs", sum(("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."UNIT_COST")*"T7"."FROM_TO_EXCHANGE_RATE") "c18", sum(("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."UNIT_COST")*"T8"."FROM_TO_EXCHANGE_RATE") "c19", "ITEM_LOT_NUMBER_ALIAS"."ON_HAND_DATE" "On_Hand_Date", "ITEM_LOT_NUMBER_ALIAS"."LOT_EXPIRY_DATE" "Lot_Expiry_Date", "ITEM_LOT_NUMBER_ALIAS"."MEMO_LOT_1" "Memo_Lot_1", "ITEM_LOT_NUMBER_ALIAS"."MEMO_LOT_2" "Memo_Lot_2", "PRP1_CATEGORY"."ITEM_CATEGORY_DESCRIPTION" "Commodity_Class_Description", "PRP2_CATEGORY"."ITEM_CATEGORY_DESCRIPTION" "c25"
 from "DW_LEGACY"."INVENTORY_ON_HAND" "INVENTORY_ON_HAND", "DW_LEGACY"."ITEM" "ITEM", "DW_LEGACY"."INVENTORY_ON_HAND_MEASURES" "INVENTORY_ON_HAND_MEASURE", "DW_LEGACY"."ITEM_LOT_NUMBERS" "ITEM_LOT_NUMBER_ALIAS", "DW_LEGACY"."ITEM_CATEGORY" "PRP1_CATEGORY", "DW_LEGACY"."ITEM_CATEGORY" "PRP2_CATEGORY", "DW_LEGACY"."FIN_CURRENCY_CONVERSION" "T7", "DW_LEGACY"."FIN_CURRENCY_CONVERSION" "T8"
 where "INVENTORY_ON_HAND"."INVENTORY_DATE"=CAST( ( :PQ1 ) AS TIMESTAMP ) and "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND">0 and "INVENTORY_ON_HAND"."BRANCH_PLANT" in (N'CINC', N'CIN2', N'CIN4', N'AUBA', N'AUB2', N'SING', N'SNG4', N'MUM3', N'SHAN') and "INVENTORY_ON_HAND"."MASTER_PLANNING_FAMILY" in (N'ATP', N'ETP', N'FBW', N'FBW', N'FCB', N'FCB', N'FCB', N'FCB', N'FCB', N'FEC', N'FEC', N'FEC', N'FEC', N'FEC', N'FRC', N'FRC', N'FRC', N'FRC', N'FRC', N'RAW', N'RAW', N'RBW', N'RCB', N'RCB', N'RCB', N'REC', N'REC', N'REC', N'RRC', N'RRC', N'RRC', N'RWW', N'TOL', N'TOL', N'TOL', N'WAG') and "T8"."FROM_CURRENCY_CODE"="INVENTORY_ON_HAND_MEASURE"."CURRENCY_CODE" and "T8"."TO_CURRENCY_CODE"='EUR' and "T8"."RATE_TYPE_CODE"='-' and "INVENTORY_ON_HAND"."INVENTORY_DATE">="T8"."EFFECTIVE_START_DATE" and "INVENTORY_ON_HAND"."INVENTORY_DATE"<="T8"."EFFECTIVE_END_DATE" and "T7"."FROM_CURRENCY_CODE"="INVENTORY_ON_HAND_MEASURE"."CURRENCY_CODE" and "T7"."TO_CURRENCY_CODE"='USD' and "T7"."RATE_TYPE_CODE"='-' and "INVENTORY_ON_HAND"."INVENTORY_DATE">="T7"."EFFECTIVE_START_DATE" and "INVENTORY_ON_HAND"."INVENTORY_DATE"<="T7"."EFFECTIVE_END_DATE" and "INVENTORY_ON_HAND"."INVENTORY_ON_HAND_SID"="INVENTORY_ON_HAND_MEASURE"."INVENTORY_ON_HAND_SID" and "INVENTORY_ON_HAND_MEASURE"."INVENTORY_ON_HAND__ITEM_SID"="ITEM"."ITEM_SID" and "ITEM_LOT_NUMBER_ALIAS"."ITEM_LOT_NUMBERS_SID"="INVENTORY_ON_HAND_MEASURE"."INVENTORY_ON_HAND__ITEM__SID1" and "PRP1_CATEGORY"."ITEM_CATEGORY_SID"="ITEM"."PRP1__ITEM_SID" and "PRP2_CATEGORY"."ITEM_CATEGORY_SID"="ITEM"."PRP2__ITEM_SID"
 group by "INVENTORY_ON_HAND"."INVENTORY_DATE", decode("INVENTORY_ON_HAND"."BRANCH_PLANT", 'CINC', 'Americas', 'CIN2', 'Americas', 'CIN4', 'Americas', 'AUBA', 'Aubange', 'AUB2', 'Aubange', 'SING', 'Singapore', 'SNG4', 'Singapore', 'MUM3', 'India', 'SHAN', 'China', 'ERROR'), "INVENTORY_ON_HAND"."BRANCH_PLANT", "ITEM"."GLOBAL_BULK_ITEM", "ITEM"."BULK_ITEM", "INVENTORY_ON_HAND_MEASURE"."ITEM_NUMBER_2ND", "ITEM"."STOCK_TYPE_CODE", "INVENTORY_ON_HAND"."GL_CLASS_CODE", "INVENTORY_ON_HAND"."LOCATION", "INVENTORY_ON_HAND"."LOT_NUMBER", "INVENTORY_ON_HAND_MEASURE"."LOT_STATUS", "INVENTORY_ON_HAND"."MASTER_PLANNING_FAMILY", "INVENTORY_ON_HAND_MEASURE"."UNIT_OF_MEASURE", "ITEM_LOT_NUMBER_ALIAS"."LOT_EXPIRY_DATE", "ITEM_LOT_NUMBER_ALIAS"."SUPPLIER_LOT_NUMBER", "ITEM_LOT_NUMBER_ALIAS"."MEMO_LOT_1", "ITEM_LOT_NUMBER_ALIAS"."MEMO_LOT_2", "ITEM_LOT_NUMBER_ALIAS"."ON_HAND_DATE", "PRP1_CATEGORY"."ITEM_CATEGORY_DESCRIPTION", "PRP2_CATEGORY"."ITEM_CATEGORY_DESCRIPTION"
